// Title: Generate HTML from a workbook with a missing font and confirm fallback to Arial using Aspose.Cells for .NET
// Common Searches: Aspose.Cells C# set a font that doesn't exist and see which font appears in the HTML export | How to detect the fallback font in HTML generated by Aspose.Cells SaveFormat.Html | C# save a workbook to HTML via MemoryStream and verify the default font-family | Aspose.Cells HTML output default to Arial when the specified font is unavailable | Check font-family declaration in HTML string produced by Aspose.Cells in .NET
// Tags: set missing font cell style Aspose.Cells | HTML export fallback font Aspose.Cells | verify font-family in Aspose.Cells HTML output | save workbook to HTML memory stream C# | default font detection Aspose.Cells HTML

using System;
using System.IO;
using Aspose.Cells;

// The example creates a new Workbook, writes text to cell A1, applies a style with a non‑existent font name, saves the workbook to HTML using a MemoryStream, and then inspects the resulting HTML for an Arial font-family declaration to confirm that Aspose.Cells falls back to the default font.
class Program
{
    static void Main()
    {
        // Create a new workbook
        Workbook workbook = new Workbook();

        // Access the first worksheet
        Worksheet worksheet = workbook.Worksheets[0];

        // Put some text into cell A1
        Cell cell = worksheet.Cells["A1"];
        cell.PutValue("Sample Text");

        // Assign a non‑existent font to the cell's style
        Style style = cell.GetStyle();
        style.Font.Name = "NonExistentFontXYZ";
        cell.SetStyle(style);

        // Save the workbook to HTML using a memory stream
        using (MemoryStream htmlStream = new MemoryStream())
        {
            workbook.Save(htmlStream, SaveFormat.Html);
            string htmlContent = System.Text.Encoding.UTF8.GetString(htmlStream.ToArray());

            // Verify that the default font (e.g., Arial) appears in the generated HTML
            bool defaultFontDetected = htmlContent.Contains("font-family:Arial") ||
                                       htmlContent.Contains("font-family:\"Arial\"") ||
                                       htmlContent.Contains("font-family: \"Arial\"");

            Console.WriteLine("Default font used in HTML: " + defaultFontDetected);
        }
    }
}
